PTA # L1-002 打印沙漏 思路：先用模拟求一下需要使用的符号和层数，然后再输出即可
#include &lt;iostream&gt; #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; char c; cin &gt;&gt; n &gt;&gt; c; int req=0; int l=1; while (2*l*l-1&lt;=n) { l++; } l--; req = 2*l*l-1; for (int i=l;i&gt;=1;i--) { cout &lt;&lt; string(l-i,&#39; &#39;) &lt;&lt; string(2*i-1,c) &lt;&lt; &#39;\n&#39;; } for (int i=2;i&lt;=l;i++) { cout &lt;&lt; string(l-i,&#39; &#39;) &lt;&lt; string(2*i-1,c) &lt;&lt; &#39;\n&#39;; } cout &lt;&lt; n-req; } L1-006 连续因子 思路：从2为开头，长度len寻找满足条件的因数列(n%因数积==0)，坑是遇到质数，因数是他本身
#include &lt;iostream&gt; #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { ll n; cin &gt;&gt; n; ll head=0,len=0; for (ll i=2;i*i&lt;=n;i++) { for (ll l=len;;l++) { ll s=1; for (ll k=0;k&lt;l;k++) { s*=i+k; } if (s&gt;n) { break; } if (n%s==0&amp;&amp;l&gt;len) { head=i; len=l; } } } if (len==0) { len=1; head=n; } cout &lt;&lt; len &lt;&lt; &#39;\n&#39;; string sep; for (ll k=0;k&lt;len;k++) { cout &lt;&lt; sep &lt;&lt; head+k; sep=&#34;*&#34;; } } L1-009 N个数求和 思路：定义一个和的分子分母a、b，然后用公式去算，最后用__gcd()求最大公约数化简，坑是有一个测试点是0，要单独处理
#include &lt;iostream&gt; #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; ll a=0,b=1; for (int i=0;i&lt;n;i++) { int x,y; scanf(&#34;%d/%d&#34;,&amp;x,&amp;y); a=a*y+x*b; b=b*y; // a x a*y+x*b // - + - = ------- } if (a==0) { cout &lt;&lt; 0; return 0; } ll g = __gcd(a,b); a/=g; b/=g; if (a*b&lt;0) { a=-abs(a); b=abs(b); } ll integer = a/b; a-=integer*b; string sep; if (integer!=0) { cout &lt;&lt; integer; sep=&#34; &#34;; } if (a!=0) { printf(&#34;%s%d/%d&#34;,sep.c_str(),a,b); } } L1-020 帅到没朋友 思路：这题的难点在于理解题目，没有朋友的人指的是发朋友圈只有一个人，那么那个人就没朋友，或者查询的时候查无此人，也是没有朋友。所以只要用集合把所有朋友圈人数&gt;1的人记下来，然后输出查询结果即可
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; unordered_set&lt;int&gt; people; for (int i=0;i&lt;n;i++) { int m; cin &gt;&gt; m; if (m==1) { int x; cin &gt;&gt; x; continue; } for (int j=0;j&lt;m;j++) { int x; cin &gt;&gt; x; people.insert(x); } } int m; cin &gt;&gt; m; unordered_set&lt;int&gt; query; bool has_handsome=false; string sep; for (int i=0;i&lt;m;i++) { int x; cin &gt;&gt; x; if (!query.count(x)) { if (!people.count(x)) { printf(&#34;%s%05d&#34;,sep.c_str(),x); sep=&#34; &#34;; has_handsome=true; } query.insert(x); } } if (!has_handsome) { cout &lt;&lt; &#34;No one is handsome&#34;; } } L1-028 判断素数 思路：先特殊情况排除x&lt;2不是质数，然后再判断x==2是质数，然后再排除偶数，最后循环用奇数验证x是否为质数，坑是数范围是2的31次方，刚好不能用int(2的31次方-1)，得用long long存(2的64次方-1)
#include &lt;iostream&gt; #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; bool is_prime(ll x) { if (x&lt;2) { return false; } if (x==2) { return true; } if ((x&amp;1)==0) { return false; } for (int i=3;i*i&lt;=x;i+=2) { if (x%i==0) { return false; } } return true; } int main() { int n; cin &gt;&gt; n; for (int i=0;i&lt;n;i++) { ll x; cin &gt;&gt; x; if (is_prime(x)) { cout &lt;&lt; &#34;Yes&#34; &lt;&lt; &#39;\n&#39;; } else { cout &lt;&lt; &#34;No&#34; &lt;&lt; &#39;\n&#39;; } } } L1-032 Left-pad 思路：先判断字符串长度和目标长度，不够就用string补齐空位，超出就用substr截取，坑就是如果你用cin读取前两个数据，那么你的cin的缓冲区会剩余一个换行符，你需要在getline读取字符串之前调用cin.ignore()忽略掉缓冲区的换行符。
#include &lt;iostream&gt; #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; char c; string s; cin &gt;&gt; n &gt;&gt; c; cin.ignore(); getline(cin,s); if (n&gt;=s.size()) { s=string(n-s.size(),c) + s; } else { s=s.substr(s.size()-n,n); } cout &lt;&lt; s; } L1-039 古风排版 思路：先把字符串存到分片存到列里面，当然可以用substr，我懒就直接遍历字符串了，然后reverse反转一下，最后在按照格式打印就行了，坑就是每列的字符数不够要补空格不然会吃WA
#include &lt;iostream&gt; #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; string s; cin.ignore(); getline(cin,s); vector&lt;string&gt; column; string s2; for (int i=0;i&lt;s.size();i++) { s2+=s[i]; if (s2.size()==n) { column.push_back(s2); s2=&#34;&#34;; } } if (s2!=&#34;&#34;) { column.push_back(s2); } reverse(column.begin(),column.end()); for (int r=0;r&lt;n;r++) { for (int c=0;c&lt;column.size();c++) { if (r&gt;=column[c].size()) { cout &lt;&lt; &#34; &#34;; } else { cout &lt;&lt; column[c][r]; } } cout &lt;&lt; &#39;\n&#39;; } } L1-043 阅览室 思路：模拟，没啥难的。坑是输入可能有问题，所以结束的书要及时erase掉，还有round(double,double)返回值还是double要转为int不然格式化会出事233
#include &lt;iostream&gt; #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; int day=0; unordered_map&lt;int,int&gt; books; int t=0,p=0; for (;;) { int id,h,m; char c; cin &gt;&gt; id &gt;&gt; c; scanf(&#34;%d:%d&#34;,&amp;h,&amp;m); if (id==0) { day++; if (p==0) { printf(&#34;0 0\n&#34;); } else { printf(&#34;%d %d\n&#34;,p,int(round(t*1.0/p))); } t=0; p=0; if (day==n) { break; } continue; } if (c==&#39;S&#39;) { books[id] = h*60+m; } else { if (books.count(id)) { p++; t+=(h*60+m)-books[id]; books.erase(id); } } } } L1-046 整除光棍 思路：看数据范围应该是高精度，直接无脑选Python，注意Python的整除是//
x=int(input()) n=1 c=1 while n%x!=0: n*=10 n+=1 c+=1 print(n//x,c) L1-049 天梯赛座位分配 思路：给每个学校都准备个vector表示每个学校的座位，然后把这些vector打包塞进一个vector表示所有学校，然后主循环中维护变量i表示每个学校对应的座位索引，还有变量seat表示座位号，遍历学校vector，通过i给每个学校相同队伍位置赋值seat，每赋值一次seat++，直到只剩一个学校seat+=2，最后输出结果。坑没多少，但是大模拟很考验耐心，慢慢调试。
#include &lt;iostream&gt; #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; vector&lt;vector&lt;int&gt;&gt; school; for (int i=0;i&lt;n;i++) { int k; cin &gt;&gt; k; vector&lt;int&gt; seat(k*10); school.push_back(seat); } int remain_school=n; int seat=1; for (int i=0;remain_school&gt;0;i++;) { for (auto &amp;s:school) { if (i&lt;s.size()) { s[i]=seat; if (remain_school==1) { seat+=2; } else { seat++; } if (i==s.size()-1) { remain_school--; } } } } int id=1; for (auto &amp;s:school) { printf(&#34;#%d\n&#34;,id); string sep; for (int i=0;i&lt;s.size();i++) { cout &lt;&lt; sep &lt;&lt; s[i]; sep=&#34; &#34;; if (i%10==9) { sep=&#34;&#34;; cout &lt;&lt; &#39;\n&#39;; } } id++; } } L1-050
